CREATE POLICY "app music readable by authenticated" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'app-music');
CREATE POLICY "app music upload own" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'app-music' AND (storage.foldername(name))[1] = (auth.uid())::text);
CREATE POLICY "app music delete own" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'app-music' AND (storage.foldername(name))[1] = (auth.uid())::text);